/** Native, ACF-backed RudnikAgro front page. */
get_header();

$field = static function (string $name): array { return function_exists('get_field') ? (array) get_field($name, get_the_ID()) : []; };
$hero = $field('rudnikagro_home_hero');
$benefits = function_exists('get_field') ? (array) get_field('rudnikagro_home_benefits', get_the_ID()) : [];
$crops = $field('rudnikagro_home_crops');
$sections = $field('rudnikagro_home_sections');
$catalogues = $field('rudnikagro_home_catalogues');
$about = $field('rudnikagro_home_about');
$blog = $field('rudnikagro_home_blog');
$knowledge = $field('rudnikagro_home_knowledge');
$shop_url = function_exists('wc_get_page_permalink') ? wc_get_page_permalink('shop') : '';
$home_products = function (int $offset = 0): array {
    return get_posts(['post_type' => 'product', 'post_status' => 'publish', 'posts_per_page' => 4, 'offset' => $offset, 'orderby' => 'date', 'order' => 'DESC']);
};
$product_card = function (WP_Post $post): void {
    $product = function_exists('wc_get_product') ? wc_get_product($post->ID) : null;
    if (!$product) { return; }
    $image_id = $product->get_image_id();
    ?>
    <article class="c-home-card">
        <a class="c-home-card__image" href="<?php echo esc_url(get_permalink($post)); ?>"><?php echo $image_id ? wp_get_attachment_image($image_id, 'medium', false, ['alt' => $product->get_name()]) : ''; ?></a>
        <h3><a href="<?php echo esc_url(get_permalink($post)); ?>"><?php echo esc_html($product->get_name()); ?></a></h3>
        <p class="c-home-card__price"><?php echo wp_kses_post($product->get_price_html()); ?></p>
        <a class="c-home-card__cart" href="<?php echo esc_url($product->add_to_cart_url()); ?>"><?php echo esc_html__('Do koszyka', 'rudnikagro'); ?></a>
    </article>
    <?php
};
?>
<main class="c-home">
    <section class="c-home-hero" data-factory-section="home-hero"<?php if (!empty($hero['image'])) : ?> style="background-image:url('<?php echo esc_url(wp_get_attachment_image_url((int) $hero['image'], 'full')); ?>')"<?php endif; ?>>
        <div class="c-home-hero__content">
            <h1><?php echo nl2br(esc_html((string) ($hero['heading'] ?? ''))); ?></h1>
            <?php if (!empty($hero['cta_label']) && $shop_url) : ?><a class="c-home-button c-home-button--outline" href="<?php echo esc_url($shop_url); ?>"><?php echo esc_html($hero['cta_label']); ?><span aria-hidden="true">â†’</span></a><?php endif; ?>
